/* Brújula — Finanzas personales v1.4. Sin claves bancarias ni secretos. */
import {accountBalanceFrom,paymentPending,availableCreditFrom,assertMovementAfterBaseline,assertBaselineSafe,movementDelta as deltaRule,paymentApplied} from './finance-rules.mjs';
import {renderExtra,extraAction,extraChange,notifyWhenOpened} from './planning-ui.mjs';
import {renderImport,importChange,importClick} from './statement-import.mjs';
import {renderAccountDetails,accountDetailAction,accountDetailChange} from './account-detail.mjs';
import {saveRecurringReview} from './recurring-review.mjs';
import {openMsiLink,saveMsiLink,updateMsiMode,msiLinkHistory} from './msi-payment-link.mjs';
import {setupInstallSupport} from './install-app.mjs';
import {renderPaydayPanel,paydayAction} from './payday-panel.mjs';
import {cycleAgenda,openCycleSettings,saveCycleSettings} from './cycle-ui.mjs';
import {createPasswordRecovery} from './password-recovery.mjs';
const $ = (s,scope=document) => scope.querySelector(s);
const $$ = (s,scope=document) => [...scope.querySelectorAll(s)];
const money = v => new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(Number(v)||0);
const num = v => Math.round((Number(v)||0)*100)/100;
const safe = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateToday=()=>{ const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}` };
const thisMonth=()=>dateToday().slice(0,7);
const printDate=s=> s ? new Date(`${s.slice(0,10)}T12:00:00`).toLocaleDateString('es-MX',{day:'2-digit',month:'short',year:'numeric'}):'—';
const getMonth=(ym,delta)=>{let [y,m]=ym.slice(0,7).split('-').map(Number); let dt=new Date(Date.UTC(y,m-1+delta,1)); return dt.toISOString().slice(0,7)};
const monthName=ym=>{let [y,m]=ym.slice(0,7).split('-').map(Number);return new Date(Date.UTC(y,m-1,15)).toLocaleDateString('es-MX',{month:'short',year:'numeric',timeZone:'UTC'})};
const uid=()=> (globalThis.crypto?.randomUUID?.()||'demo-'+Math.random().toString(36).slice(2));
const DB_TABLES=['accounts','movements','installments','statements','loans','loan_payments','recurring_bills','recurring_checks','recurring_postings','msi_payment_links','budgets'];
const titles={dashboard:'Resumen',accounts:'Cuentas y tarjetas',movements:'Movimientos',installments:'Compras a meses',statements:'Cortes y conciliación',loans:'Créditos',analytics:'Análisis de gastos',bills:'Gastos fijos',calendar:'Calendario financiero',budgets:'Presupuestos',import:'Importar estado de cuenta',reminders:'Recordatorios',amortization:'Amortización','account-detail':'Detalle de cuenta'};
const kinds={purchase:'Compra con tarjeta',expense:'Gasto',income:'Ingreso',payment:'Pago a tarjeta',refund:'Devolución/bonificación',fee:'Comisión',interest:'Intereses',adjustment_plus:'Ajuste positivo',adjustment_minus:'Ajuste negativo',transfer_in:'Entrada por transferencia',transfer_out:'Salida por transferencia'};
const categories=['Alimentos','Supermercado','Gasolina','Transporte','Salud','Hogar','Entretenimiento','Suscripciones','Compras','Vehículo','Servicios','Retiros','Ahorro','Ingreso','Otros'];
const colors=['#5b54df','#1874ad','#1d986e','#d86e5a','#9d6cd5','#26334d'];
let mode='demo', sb=null, page='dashboard', state={}, toastTimer=null;
const fresh=()=>Object.fromEntries(DB_TABLES.map(t=>[t,[]]));
const sample=()=>{
 const d=fresh(), month=thisMonth();
 const c1={id:'demo-cc1',name:'Tarjeta principal',bank_name:'Banco ejemplo',kind:'credit',last4:'4242',credit_limit:60000,opening_balance:9000,cutoff_day:24,due_day:13,cutoff_tolerance_days:2,payment_alert_days:2,active:true};
 const c2={id:'demo-cc2',name:'Tarjeta de compras',bank_name:'Banco ejemplo 2',kind:'credit',last4:'1991',credit_limit:25000,opening_balance:2200,cutoff_day:14,due_day:4,cutoff_tolerance_days:2,payment_alert_days:2,active:true};
 const debit={id:'demo-debit',name:'Cuenta de nómina',bank_name:'Banco ejemplo',kind:'debit',last4:'8844',credit_limit:0,opening_balance:14500,active:true};
 const cash={id:'demo-cash',name:'Efectivo',bank_name:'Billetera',kind:'cash',credit_limit:0,opening_balance:850,active:true};
 d.accounts=[c1,c2,debit,cash];
 d.statements=[{id:'demo-st1',account_id:c1.id,close_date:month+'-24',due_date:getMonth(month,1)+'-13',no_interest_amount:10600,bank_available:48500},{id:'demo-st2',account_id:c2.id,close_date:month+'-14',due_date:getMonth(month,1)+'-04',no_interest_amount:2300,bank_available:22500}];
 d.movements=[{id:'demo-m1',account_id:c1.id,transaction_date:month+'-08',kind:'purchase',amount:1600,category:'Supermercado',description:'Despensa'},{id:'demo-m2',account_id:c2.id,transaction_date:month+'-10',kind:'purchase',amount:300,category:'Gasolina',description:'Gasolina'},{id:'demo-m3',account_id:debit.id,transaction_date:month+'-11',kind:'expense',amount:375,category:'Alimentos',description:'Comida'},{id:'demo-m4',account_id:cash.id,transaction_date:month+'-12',kind:'expense',amount:140,category:'Transporte',description:'Taxi'},{id:'demo-m5',account_id:debit.id,transaction_date:month+'-05',kind:'income',amount:8000,category:'Ingreso',description:'Pago de nómina'}];
 d.installments=[{id:'demo-msi1',account_id:c1.id,description:'Compra electrodoméstico',original_amount:5400,months:9,first_charge_month:getMonth(month,-1)+'-01',installments_paid:1,status:'active'}];
 d.loans=[{id:'demo-loan',name:'Vehículo (ejemplo)',financed_amount:185000,monthly_payment:4700,term_months:48,next_due_date:getMonth(month,1)+'-08',payroll_deduction:true,status:'active',down_payment:40000,lender:'Financiera ejemplo'}];
 d.loan_payments=[{id:'demo-lp1',loan_id:'demo-loan',amount:4700,principal_part:2900,interest_part:1800,payment_date:month+'-01',note:'Descuento de nómina de ejemplo'}];
 return d;
};
const toast=(message,isError=false)=>{const t=$('#toast');t.textContent=message;t.style.background=isError?'#a74051':'#17243c';t.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.add('hidden'),4400)};
const account=id=>state.accounts.find(a=>a.id===id);
const linkedPayments=stmt=>state.movements.filter(m=>m.statement_id===stmt.id&&m.kind==='payment').reduce((s,m)=>s+num(m.amount),0);
const pendingStatement=stmt=>paymentPending(stmt,state.movements);
const latestStatement=id=>state.statements.filter(s=>s.account_id===id).sort((a,b)=>b.close_date.localeCompare(a.close_date))[0];
const movementDelta=(m,a)=>deltaRule(m,a);
const accountBalance=a=>accountBalanceFrom(a,state.movements);
const accountAvailable=a=>a.kind==='credit'?num(a.credit_limit)-accountBalance(a):accountBalance(a);
const spending=m=>['purchase','expense'].includes(m.kind);
const personalSpend=()=>state.movements.filter(spending).reduce((s,m)=>s+num(m.amount),0);
const thisMonthSpend=()=>state.movements.filter(m=>m.transaction_date?.startsWith(thisMonth())&&spending(m)).reduce((s,m)=>s+num(m.amount),0);
const thisMonthIncome=()=>state.movements.filter(m=>m.transaction_date?.startsWith(thisMonth())&&m.kind==='income').reduce((s,m)=>s+num(m.amount),0);
const dueStatements=()=>state.accounts.filter(a=>a.kind==='credit').map(a=>({a,s:latestStatement(a.id)})).filter(x=>x.s).sort((a,b)=>a.s.due_date.localeCompare(b.s.due_date));
const durationDays=date=>Math.round((new Date(date+'T12:00:00')-new Date(dateToday()+'T12:00:00'))/86400000);

// Las fechas de los cortes anteriores son datos confirmados; el siguiente corte es solo una previsión.
const monthDay=(ym,day)=>`${ym}-${String(Math.min(Number(day),28)).padStart(2,'0')}`;
const isoOffset=(iso,days)=>{const x=new Date(iso+'T12:00:00');x.setDate(x.getDate()+days);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
const daysBetween=(from,to)=>Math.round((new Date(to+'T12:00:00')-new Date(from+'T12:00:00'))/86400000);
const cycleInfo=(a,today=dateToday())=>{
 const latest=latestStatement(a.id),tolerance=Math.max(0,Math.min(3,Number(a.cutoff_tolerance_days??2)));
 const day=a.cutoff_day || (latest?.close_date?Number(latest.close_date.slice(-2)):null);
 if(!day)return {key:'missing',label:'Configura el corte',description:'Falta día de corte estimado',next:null,confirmed:false,rank:0};
 const currentMonth=today.slice(0,7);
 if(latest && latest.close_date<=today){
  const next=monthDay(getMonth(latest.close_date.slice(0,7),1),day);
  const gap=daysBetween(today,next);
  if(today===latest.close_date)return {key:'today',label:'Corta hoy',description:'Espera a que el banco confirme el nuevo periodo',next,confirmed:false,rank:1};
  if(gap < -tolerance)return {key:'verify',label:'Corte sin confirmar',description:'Actualiza el corte más reciente en el banco',next,confirmed:false,rank:0};
  if(gap<=tolerance)return {key:'soon',label:'Corte cercano · verificar',description:'El banco podría mover la fecha ±'+tolerance+' días',next,confirmed:false,rank:1};
  return {key:'ready',label:'Después del corte',description:'Último corte confirmado '+printDate(latest.close_date),next,confirmed:true,rank:4};
 }
 // Sin un estado de cuenta vigente no debemos presentar una recomendación confirmada.
 const predicted=monthDay(currentMonth,day),gap=daysBetween(today,predicted);
 if(gap>tolerance)return {key:'waiting',label:'Aún no corta',description:'Fecha de corte orientativa',next:predicted,confirmed:false,rank:1};
 if(Math.abs(gap)<=tolerance)return {key:'soon',label:'Corte cercano · verificar',description:'La fecha puede variar ±'+tolerance+' días',next:predicted,confirmed:false,rank:1};
 return {key:'estimated',label:'Posible nuevo periodo',description:'Confirma el corte real antes de utilizarla',next:monthDay(getMonth(currentMonth,1),day),confirmed:false,rank:2};
};
// El disponible informado en un corte es una fotografía histórica: proyectar movimientos posteriores.
const shownAvailable=a=>availableCreditFrom(a,state.statements,state.movements,dateToday());
const cardPriority=(a,today=dateToday())=>{
 const c=cycleInfo(a,today), available=shownAvailable(a);
 if(available<1) return {...c,rank:0,label:'Sin crédito disponible',available};
 return {...c,available};
};
const cardGuidance=()=>state.accounts.filter(a=>a.kind==='credit'&&a.active!==false).map(a=>({a,cycle:cardPriority(a)})).sort((x,y)=>y.cycle.rank-x.cycle.rank || (y.cycle.next||'').localeCompare(x.cycle.next||'') || y.cycle.available-x.cycle.available);
const paymentWarnings=()=>dueStatements().filter(({s})=>pendingStatement(s)>0).map(({a,s})=>({a,s,days:durationDays(s.due_date),alertDays:Number(a.payment_alert_days??2)})).filter(x=>x.days<=x.alertDays);

function monthlyAt(plan,i){const total=Math.round(num(plan.original_amount)*100), regular=plan.monthly_amount!=null?Math.round(num(plan.monthly_amount)*100):Math.round(total/plan.months);return (i===plan.months-1?total-regular*(plan.months-1):regular)/100}
const remainingMSI=p=>{if(p.status!=='active')return 0;let s=0;for(let i=Number(p.installments_paid)||0;i<Number(p.months);i++)s+=monthlyAt(p,i);return num(s)};
const scheduledMonth=(plan,ym)=>{if(plan.status!=='active')return 0;const d=Number(ym.slice(0,4))*12+Number(ym.slice(5,7)) - (Number(plan.first_charge_month.slice(0,4))*12+Number(plan.first_charge_month.slice(5,7)));if(d<0||d>=plan.months||d<plan.installments_paid)return 0;return monthlyAt(plan,d)};
const loanPaid=l=>state.loan_payments.filter(p=>p.loan_id===l.id);
const principalStatus=l=>{const payments=loanPaid(l);return payments.length===0?{known:false,balance:num(l.financed_amount)}:payments.every(p=>p.principal_part!==null&&p.principal_part!==undefined)?{known:true,balance:Math.max(0,num(l.financed_amount)-payments.reduce((s,p)=>s+num(p.principal_part),0))}:{known:false,balance:null}};
function showShell(){ $('#gate').classList.add('hidden');$('#shell').classList.remove('hidden');$('#session-label').textContent=mode==='demo'?'Demo · temporal':'Conectado';$('#logout').textContent=mode==='demo'?'Volver ↗':'Salir ↗';render();notifyWhenOpened(featureHost()).catch(()=>{}) }
function featureHost(){return {mode,state,sb,account,money,num,safe,printDate,dateToday,thisMonth,getMonth,categories,accountBalance,pendingStatement,field,choose,modalOpen,persist,remove,loadData,toast,uid,render,setPage:(p)=>{page=p;render()},shownAvailable,kinds,openMovement:(id=null,accountId=null,startKind=null)=>openForm('movements',id,accountId,startKind)}}
function render(){const root=$('#content');$('#crumb').textContent=titles[page]||page;$$('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));const normal=({dashboard:renderDashboard,accounts:renderAccounts,movements:renderMovements,installments:renderInstallments,statements:renderStatements,loans:renderLoans,analytics:renderAnalytics})[page];root.innerHTML=normal?normal():page==='account-detail'?renderAccountDetails(featureHost()):page==='import'?renderImport(featureHost()):renderExtra(page,featureHost())||'<p>Página no disponible</p>';if(page==='movements')updateMovementTable()}
const head=(title,sub,btn='',action='')=>`<div class="page-head"><div><h1>${title}</h1><p class="muted">${sub}</p></div>${btn?`<button class="btn primary small-btn" data-act="${action}">+ ${btn}</button>`:''}</div>`;
const info=(title,val,detail,symbol='◈',featured=false)=>`<div class="panel stat ${featured?'featured':''}"><label>${title}</label><strong>${val}</strong><span class="hint">${detail}</span><span class="symbol">${symbol}</span></div>`;
const listEmpty=(name='No hay registros todavía')=>`<div class="empty"><strong>${name}</strong><span>Agrega tu primer registro para comenzar.</span></div>`;
const transactionName=m=>safe(m.description||m.merchant||kinds[m.kind]||'Movimiento');
const typeMark=a=>a.kind==='credit'?'💳':a.kind==='cash'?'💵':'🏦';
function renderCardCyclePanel(){
 const cards=cardGuidance(),ready=cards.filter(({cycle})=>cycle.key==='ready'&&cycle.available>0),warnings=paymentWarnings();
 return `<section class="panel section cycle-panel"><div class="section-title"><div><h3>💳 ¿Qué tarjeta me conviene utilizar hoy?</h3><p class="muted small">Ordenadas por corte registrado, próximo corte y crédito disponible estimado.</p></div><button class="linkbtn" data-page="statements">Actualizar cortes →</button></div>
 ${warnings.length?`<div class="notice warn"><b>⏰ Atención a pagos:</b> ${warnings.map(({a,s,days})=>`${safe(a.name)}: ${money(pendingStatement(s))} · ${days<0?'venció hace '+Math.abs(days)+' días':days===0?'vence hoy':'vence en '+days+' días'}`).join(' · ')}. Se usa la fecha real de pago registrada del banco.</div>`:''}
 ${ready.length?`<p class="cycle-highlight">✅ ${ready.length===1?'Tarjeta con nuevo periodo confirmado':'Tarjetas con nuevo periodo confirmado'}: ${ready.map(({a})=>safe(a.name)).join(', ')}</p>`:'<p class="cycle-highlight">ℹ️ No hay un nuevo ciclo confirmado para recomendar; revisa tus últimos cortes.</p>'}
 <div class="cycle-grid">${cards.map(({a,cycle})=>`<div class="cycle-card ${cycle.key==='ready'?'is-ready':cycle.key==='soon'?'is-soon':''}"><div class="cycle-top"><strong>${safe(a.name)}</strong><span class="cycle-tag ${cycle.key==='ready'?'cycle-green':cycle.rank===0?'cycle-gray':'cycle-amber'}">${safe(cycle.label)}</span></div><div class="cycle-available"><span>Crédito disponible estimado</span><strong>${money(cycle.available)}</strong></div><div class="cycle-detail">${safe(cycle.description)}</div><div class="cycle-detail">${cycle.next?'Próximo corte previsto: <b>'+printDate(cycle.next)+'</b>':'Fecha de corte pendiente'}</div><button class="btn-mini" data-act="card-statement" data-id="${safe(a.id)}">Registrar corte real</button></div>`).join('')||listEmpty('Agrega tus tarjetas para ver este panel')}</div>
 <p class="tip" style="margin:14px 0 0">⚠️ «Después del corte» significa que las compras normalmente pasan al siguiente periodo, no que el banco apruebe automáticamente una compra. Las fechas previstas pueden variar; el disponible puede diferir por retenciones o cargos no registrados. Confirma con tu banco.</p></section>`;
}
function renderDashboard(){
 const credits=state.accounts.filter(a=>a.kind==='credit'), cash=state.accounts.filter(a=>a.kind!=='credit'), ds=dueStatements();const legacyCards=credits.filter(a=>!a.opening_balance_date);
 const owed=credits.reduce((s,a)=>s+Math.max(0,accountBalance(a)),0),liquid=cash.reduce((s,a)=>s+accountBalance(a),0),need=ds.reduce((s,{s:t})=>s+pendingStatement(t),0);
 const last=state.movements.slice().sort((a,b)=>b.transaction_date.localeCompare(a.transaction_date)).slice(0,6);
 return `${head('Hola, tus finanzas 👋','Control general de tus cuentas, compromisos y movimientos.')}${mode==='demo'?'<div class="notice">🧪 <b>Modo demostración.</b> Todos los datos son ficticios y no se guardan. Para usar tus cifras reales, conecta una nueva base Supabase.</div>':''}${legacyCards.length?'<div class="notice warn">⚠️ '+legacyCards.length+' tarjeta(s) sin fecha de saldo inicial. Configúralas desde Mis cuentas y tarjetas para evitar duplicar compras anteriores.</div>':''}
 <div class="grid stats">${info('Pagos según estados de cuenta',money(need),'Pendiente según últimos cortes registrados','◎',true)}${info('Deuda en tarjetas (estimada)',money(owed),`${credits.length} tarjetas registradas`,'▤')}${info('Efectivo y débito (estimado)',money(liquid),'No incluye saldos de créditos','◫')}${info('Gasto de este mes',money(thisMonthSpend()),`Ingresos registrados: ${money(thisMonthIncome())}`,'◷')}</div>
 ${renderPaydayPanel(featureHost())}
 ${renderCardCyclePanel()}
 ${cycleAgenda(state,dateToday())}
  <div class="grid twocol"><section class="panel section"><div class="section-title"><h3>Mis tarjetas y cuentas</h3><button class="linkbtn" data-page="accounts">Ver todas →</button></div><div class="account-list">${state.accounts.length?state.accounts.slice(0,6).map(a=>`<div class="account-row"><div class="ident"><div class="tile-icon">${typeMark(a)}</div><div><strong>${safe(a.name)}</strong><small>${safe(a.bank_name)} · ${a.last4?'•••• '+safe(a.last4):a.kind==='cash'?'Efectivo':a.kind==='debit'?'Débito':'Crédito'}</small></div></div><div class="val"><strong>${money(a.kind==='credit'?accountBalance(a):accountAvailable(a))}</strong><small>${a.kind==='credit'?'Deuda estimada':'Saldo estimado'}</small><button class="btn-mini" data-act="view-account" data-id="${a.id}">Ver movimientos</button></div></div>`).join(''):listEmpty()}</div></section>
 <section class="panel section"><div class="section-title"><h3>Próximos pagos</h3><button class="linkbtn" data-page="statements">Registrar próximo pago →</button></div><div class="due-list">${ds.length?ds.map(({a,s})=>{const days=durationDays(s.due_date),p=pendingStatement(s);return `<div class="due-row"><div><strong>${safe(a.name)}</strong><small>Vence ${printDate(s.due_date)} · ${days<0?'Vencido':days===0?'Hoy':days+' días'}</small></div><div class="val"><strong>${money(p)}</strong><small><span class="pill ${days<5?'orange':'green'}">${p<=0?'Cubierto':days<0?'Vencido':'Por pagar'}</span></small></div></div>`}).join(''):listEmpty('Aún no hay estados de cuenta')}</div><p class="tip">Se usa el importe que registraste del banco, menos pagos vinculados al corte.</p></section></div>
 <div class="grid twocol"><section class="panel section"><div class="section-title"><h3>Actividad reciente</h3><button class="linkbtn" data-page="movements">Todos los movimientos →</button></div><div class="activity-list">${last.length?last.map(m=>{let a=account(m.account_id);return `<div class="activity-row"><div class="ident"><div class="tile-icon">${m.kind==='income'?'↓':m.kind==='payment'?'✓':'↗'}</div><div><strong>${transactionName(m)}</strong><small>${printDate(m.transaction_date)} · ${safe(a?.name||'—')}</small></div></div><div class="val"><strong class="${['income','refund','payment'].includes(m.kind)?'positive':''}">${money(m.amount)}</strong><small>${safe(kinds[m.kind]||m.kind)}</small></div></div>`}).join(''):listEmpty()}</div></section>
 <section class="panel section"><div class="section-title"><h3>Compromisos financieros</h3><button class="linkbtn" data-page="loans">Ver créditos →</button></div><div class="summary-table"><div class="summary-line"><span>MSI pendientes</span><b>${money(state.installments.reduce((s,p)=>s+remainingMSI(p),0))}</b></div><div class="summary-line"><span>Mensualidades MSI de este mes</span><b>${money(state.installments.reduce((s,p)=>s+scheduledMonth(p,thisMonth()),0))}</b></div><div class="summary-line"><span>Créditos activos</span><b>${state.loans.filter(l=>l.status==='active').length}</b></div><div class="summary-line"><span>Mensualidades de créditos declaradas</span><b>${money(state.loans.filter(l=>l.status==='active').reduce((s,l)=>s+num(l.monthly_payment),0))}</b></div></div><div class="separator"></div><p class="tip">Las mensualidades MSI se muestran por separado para no duplicar deuda ya registrada en la compra original.</p></section></div>`;
}
function renderAccounts(){return `${head('Cuentas y tarjetas','Registra tarjetas desde un saldo inicial confirmado y evita contar dos veces los MSI.','Nueva tarjeta guiada','new-account')+`<div class="inline-actions"><button class="btn outline small-btn" data-act="new-cash-account">+ Efectivo o débito</button></div>`}<div class="notice">💡 La deuda y el disponible son <b>estimaciones</b> a partir de saldo inicial y movimientos. Usa los importes bancarios oficiales para conciliarlos.</div><div class="account-cards">${state.accounts.map(a=>`<div class="bank-card"><div class="bank-top"><span>${typeMark(a)} ${safe(a.name)}</span><small>${a.last4?'•••• '+safe(a.last4):a.kind==='cash'?'EFECTIVO':'CUENTA'}</small></div><div><div class="bal-label">${a.kind==='credit'?'Deuda estimada':'Saldo estimado'}</div><div class="bal-big">${money(accountBalance(a))}</div><div class="bottom"><span>${a.kind==='credit'?`Disponible estimado ${money(shownAvailable(a))} · ${a.opening_balance_date?'Inicio '+printDate(a.opening_balance_date):'⚠ Inicio pendiente'} · ${safe(cycleInfo(a).label)}`:safe(a.bank_name||'Control personal')}</span><div class="inline-actions"><button class="btn-mini" data-act="view-account" data-id="${a.id}">Ver movimientos</button>${a.kind==='credit'?`<button class="btn-mini" data-act="card-cycle" data-id="${a.id}">Configurar ciclo</button>`:''}<button class="btn-mini" data-act="edit-account" data-id="${a.id}">Editar</button></div></div></div></div>`).join('')||listEmpty()}</div><section class="panel section" style="margin-top:22px"><div class="section-title"><h3>Detalle por cuenta</h3></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Nombre</th><th>Tipo</th><th>Límite</th><th>Corte</th><th>Fecha pago (orientativa)</th><th></th></tr></thead><tbody>${state.accounts.map(a=>`<tr><td><button class="linkbtn" data-act="view-account" data-id="${a.id}">${safe(a.name)}</button></td><td>${a.kind==='credit'?'Crédito':a.kind==='debit'?'Débito':'Efectivo'}</td><td>${a.kind==='credit'?money(a.credit_limit):'—'}</td><td>${a.cutoff_day||'—'}</td><td>${a.due_day||'—'}</td><td><button class="table-btn danger" data-act="delete" data-table="accounts" data-id="${a.id}">Eliminar</button></td></tr>`).join('')}</tbody></table></div></section>`}
function renderMovements(){let accountOpt='<option value="">Todas las cuentas</option>'+state.accounts.map(a=>`<option value="${a.id}">${safe(a.name)}</option>`).join('');return `${head('Movimientos','Cada compra, pago, comisión, abono o gasto en efectivo, sin mezclar saldos.','Registrar','new-movement')}<div class="filterbar"><input type="search" id="mov-search" placeholder="Buscar comercio o concepto"><select id="mov-account">${accountOpt}</select><select id="mov-kind"><option value="">Todos los movimientos</option>${Object.entries(kinds).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><button class="btn outline small-btn" data-act="export">Exportar CSV</button></div><section class="panel section"><div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Concepto</th><th>Cuenta</th><th>Tipo</th><th>Categoría</th><th>Importe</th><th></th></tr></thead><tbody id="mov-list"></tbody></table></div></section><p class="tip">Al pagar una tarjeta, registra el pago como “Pago a tarjeta” en la cuenta de crédito. Si también salió dinero de una cuenta de débito, registra una “Salida por transferencia” en esa cuenta, no otro gasto.</p>`}
function updateMovementTable(){if(page!=='movements')return;const search=($('#mov-search')?.value||'').toLowerCase(),a=$('#mov-account')?.value||'',k=$('#mov-kind')?.value||'';let items=state.movements.filter(m=>(!a||m.account_id===a)&&(!k||m.kind===k)&&(`${m.description||''} ${m.merchant||''} ${m.category||''}`).toLowerCase().includes(search)).sort((a,b)=>b.transaction_date.localeCompare(a.transaction_date));$('#mov-list').innerHTML=items.length?items.map(m=>`<tr><td>${printDate(m.transaction_date)}</td><td><b>${transactionName(m)}</b></td><td>${safe(account(m.account_id)?.name||'—')}</td><td>${safe(kinds[m.kind]||m.kind)}</td><td>${safe(m.category)}</td><td><b>${money(m.amount)}</b></td><td><span class="inline-flex"><button class="table-btn" data-act="edit-movement" data-id="${m.id}">Editar</button><button class="table-btn danger" data-act="delete" data-table="movements" data-id="${m.id}">×</button></span></td></tr>`).join(''):`<tr><td colspan="7">${listEmpty('Sin movimientos con estos filtros')}</td></tr>`}
function renderInstallments(){const active=state.installments.filter(p=>p.status==='active');const monthly=active.reduce((s,p)=>s+scheduledMonth(p,thisMonth()),0);return `${head('Compras a meses','Controla cada parcialidad sin contar dos veces el monto total de la compra.','Nuevo plan MSI','new-installment')}<div class="grid stats">${info('Planes activos',active.length,'Compras financiadas','▦')}${info('Mensualidades este mes',money(monthly),'Según primer mes indicado','◷')}${info('Saldo MSI pendiente',money(active.reduce((s,p)=>s+remainingMSI(p),0)),'Informativo, ya incluido en la deuda de tarjeta','◎')}${info('Mes siguiente',money(active.reduce((s,p)=>s+scheduledMonth(p,getMonth(thisMonth(),1)),0)),'Estimado por calendario','→')}</div><div class="notice warn">⚠️ <b>Importante:</b> registra la compra total de MSI como compra en Movimientos si deseas estimar el crédito disponible. Aquí controlas el calendario y vinculas cada mensualidad con un pago real, existente o nuevo. Vincular nunca genera un segundo descuento. Un plan anterior ya está incluido en el saldo inicial. Un plan nuevo exige enlazar la compra registrada tras esa fecha. Verifica el primer mes de cobro en tu estado de cuenta.</div><div class="grid twocol">${state.installments.map(p=>{let a=account(p.account_id),n=Number(p.installments_paid)||0,paid=100*n/Number(p.months);return `<section class="panel section"><div class="section-title"><div><h3>${safe(p.description)}</h3><span class="muted small">${safe(a?.name||'—')} · ${money(p.original_amount)} original · ${p.entry_type==='new_purchase'?'Compra vinculada':'Dentro del saldo inicial'}</span></div><span class="pill ${p.status==='active'?'':'green'}">${safe(p.status)}</span></div><div class="date-row"><b>${n} de ${p.months} mensualidades pagadas</b><b>${Math.round(paid)}%</b></div><div class="progress"><span style="width:${paid}%"></span></div><div class="separator"></div><div class="summary-table"><div class="summary-line"><span>Siguiente mensualidad</span><b>${n<p.months?money(monthlyAt(p,n)):'—'}</b></div><div class="summary-line"><span>Capital restante</span><b>${money(remainingMSI(p))}</b></div><div class="summary-line"><span>Primer mes de cargo</span><b>${monthName(p.first_charge_month)}</b></div></div>${msiLinkHistory(state,p)}<div class="inline-actions" style="margin-top:18px"><button class="btn-mini" data-act="edit-installment" data-id="${p.id}">Editar</button>${n<p.months&&p.status==='active'?`<button class="btn-mini" data-act="msi-link" data-id="${p.id}">Vincular pago de mensualidad ${n+1}</button>`:''}<button class="btn-mini" data-act="delete" data-table="installments" data-id="${p.id}">Eliminar</button></div></section>`}).join('')||`<section class="panel section">${listEmpty('Aún no tienes planes MSI')}</section>`}</div>`}
function renderStatements(){const results=dueStatements();return `${head('Cortes y conciliación','Registra el importe oficial de cada estado de cuenta y compáralo con tus registros.','Registrar estado de cuenta','new-statement')}<div class="notice">✅ <b>No necesitas capturar todas las compras.</b> Para saber cuánto debes pagar a Stori, HSBC u otra tarjeta, registra <b>la fecha del corte, el vencimiento y el pago para no generar intereses</b> indicados por el banco. La deuda total o el crédito disponible no permiten deducir ese importe. Cuando realices un pago, vincúlalo al corte para actualizar cuánto falta.</div>${cycleAgenda(state,dateToday())}<section class="panel section"><div class="section-title"><h3>Últimos estados de cuenta</h3></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Tarjeta</th><th>Corte</th><th>Vencimiento</th><th>Pago sin intereses</th><th>Pagos y ajustes previos</th><th>Pendiente</th><th>Disponible banco</th><th></th></tr></thead><tbody>${state.statements.slice().sort((a,b)=>b.close_date.localeCompare(a.close_date)).map(s=>`<tr><td>${safe(account(s.account_id)?.name||'—')}</td><td>${printDate(s.close_date)}</td><td>${printDate(s.due_date)}</td><td>${money(s.no_interest_amount)}</td><td>${money(paymentApplied(s,state.movements))}</td><td><b>${money(pendingStatement(s))}</b></td><td>${s.bank_available==null?'—':money(s.bank_available)}</td><td><button class="table-btn" data-act="edit-statement" data-id="${s.id}">Editar</button></td></tr>`).join('')||`<tr><td colspan="8">${listEmpty('Aún no hay estados de cuenta')}</td></tr>`}</tbody></table></div></section><section class="panel section"><h3>Cómo reconciliar cada corte</h3><p class="muted small">1. Registra el estado bancario: corte, vencimiento, pago para no generar intereses y crédito disponible. 2. Registra las compras y cargos en Movimientos. 3. Vincula cada abono de tipo «Pago a tarjeta» al estado de cuenta correcto. 4. Compara el pago pendiente y verifica diferencias con el banco.</p><p class="tip">Los cargos no reconocidos, bonificaciones, retenciones y disposiciones de efectivo se deben verificar por separado.</p></section>`}
function renderLoans(){const active=state.loans.filter(l=>l.status==='active');return `${head('Créditos y financiamientos','Incluye tu vehículo, pagos mensuales y descuentos de nómina.','Agregar crédito','new-loan')}<div class="grid stats">${info('Créditos activos',active.length,'Financiamientos registrados','♧')}${info('Pago mensual declarado',money(active.reduce((s,l)=>s+num(l.monthly_payment),0)),'No incluye MSI de tarjetas','◷')}${info('Monto originalmente financiado',money(state.loans.reduce((s,l)=>s+num(l.financed_amount),0)),'Todos los créditos','▤')}${info('Pagos ya registrados',money(state.loan_payments.reduce((s,p)=>s+num(p.amount),0)),'Incluye descuentos por nómina','✓')}</div><div class="grid twocol">${state.loans.map(l=>{let t=principalStatus(l),ps=loanPaid(l);return `<section class="panel section loan-card"><div class="section-title"><h3>${safe(l.name)}</h3><span class="pill ${l.status==='active'?'':'green'}">${safe(l.status)}</span></div><div class="muted small">${safe(l.lender||'Financiamiento')} · ${l.payroll_deduction?'Descuento de nómina':'Pago manual'}</div><div class="overline" style="margin-top:16px">${t.known?'Capital pendiente estimado':'Capital pendiente por confirmar'}</div><div class="large-number">${t.balance!==null?money(t.balance):'Sin desglose de capital'}</div><div class="summary-table"><div class="summary-line"><span>Mensualidad</span><b>${l.monthly_payment!=null?money(l.monthly_payment):'No registrada'}</b></div><div class="summary-line"><span>Plazo</span><b>${l.term_months?l.term_months+' meses':'No registrado'}</b></div><div class="summary-line"><span>Próximo vencimiento</span><b>${printDate(l.next_due_date)}</b></div><div class="summary-line"><span>Pagos registrados</span><b>${ps.length}</b></div></div><div class="inline-actions" style="margin-top:18px"><button class="btn-mini" data-act="new-loan-payment" data-id="${l.id}">+ Pago</button><button class="btn-mini" data-act="edit-loan" data-id="${l.id}">Editar</button><button class="btn-mini" data-act="delete" data-table="loans" data-id="${l.id}">Eliminar</button></div></section>`}).join('')||`<section class="panel section">${listEmpty('Aún no registras préstamos')}</section>`}</div><section class="panel section"><h3>Historial de pagos de crédito</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Crédito</th><th>Total pagado</th><th>Capital</th><th>Interés</th><th></th></tr></thead><tbody>${state.loan_payments.slice().sort((a,b)=>b.payment_date.localeCompare(a.payment_date)).map(p=>`<tr><td>${printDate(p.payment_date)}</td><td>${safe(state.loans.find(l=>l.id===p.loan_id)?.name||'—')}</td><td>${money(p.amount)}</td><td>${p.principal_part==null?'Por indicar':money(p.principal_part)}</td><td>${p.interest_part==null?'Por indicar':money(p.interest_part)}</td><td><button class="table-btn" data-act="edit-loan-payment" data-id="${p.id}">Editar</button></td></tr>`).join('')||`<tr><td colspan="6">${listEmpty('Sin pagos registrados')}</td></tr>`}</tbody></table></div><p class="tip">Un descuento de nómina no crea automáticamente otro gasto en cuenta bancaria. Registra el desglose de capital para estimar el saldo insoluto.</p></section>`}
function renderAnalytics(){const data=state.movements.filter(m=>m.transaction_date?.startsWith(thisMonth())&&spending(m));const sums={};data.forEach(m=>sums[m.category]=(sums[m.category]||0)+num(m.amount));const cats=Object.entries(sums).sort((a,b)=>b[1]-a[1]);const total=data.reduce((s,m)=>s+num(m.amount),0);return `${head('Análisis de gastos','Entiende cómo distribuyes tu dinero este mes.') }<div class="grid stats">${info('Gastos registrados',money(total),'Mes actual','◷')}${info('Ingresos registrados',money(thisMonthIncome()),'Mes actual','↓')}${info('Movimientos del mes',state.movements.filter(m=>m.transaction_date?.startsWith(thisMonth())).length,'Entradas, salidas y pagos','⇄')}${info('Categorías con gastos',cats.length,'Mes actual','◫')}</div><section class="panel section"><div class="section-title"><h3>Gastos por categoría</h3><span class="pill">${monthName(thisMonth())}</span></div>${cats.map(([name,v])=>`<div class="bar-row"><span>${safe(name)}</span><div class="progress"><span style="width:${total?100*v/total:0}%"></span></div><b>${money(v)}</b></div>`).join('')||listEmpty('Aún no hay gastos este mes')}<div class="separator"></div><p class="tip">Los pagos a tarjetas, las transferencias y los abonos MSI no se cuentan como nuevos gastos. Las compras ya se contabilizan al registrarlas.</p></section>`}
function field(name,label,type='text',value='',extra='',full=false){return `<label class="field ${full?'full-span':''}">${label}<input name="${name}" type="${type}" value="${safe(value??'')}" ${extra}></label>`}
function choose(name,label,options,value='',full=false){return `<label class="field ${full?'full-span':''}">${label}<select name="${name}" ${options.some(([v])=>v==='')?'':'required'}>${options.map(([v,l])=>`<option value="${safe(v)}" ${String(v)===String(value)?'selected':''}>${safe(l)}</option>`).join('')}</select></label>`}
const optsAccounts=(filter)=>state.accounts.filter(a=>!filter||a.kind===filter).map(a=>[a.id,`${a.name}${a.last4?' • '+a.last4:''}`]);
function bodyButtons(){return `<div class="form-footer"><button type="button" class="btn outline" data-act="close">Cancelar</button><button type="submit" class="btn primary">Guardar registro</button></div>`}
function modalOpen(title,table,html,id=null){$('#modal-title').textContent=title;const f=$('#modal-form');f.dataset.table=table;f.dataset.id=id||'';f.innerHTML=`<div class="form-grid">${html}</div>${bodyButtons()}`;$('#modal').classList.remove('hidden');setTimeout(()=>f.querySelector('input,select,textarea')?.focus(),20)}
const modalClose=()=>{$('#modal').classList.add('hidden');$('#modal-form').reset()};

/* Asistente de alta: tres pasos y una sola transacción Supabase.
   Las tarjetas previas siguen legacy hasta que el propietario fije voluntariamente su fecha. */
function openCreditWizard(id=null){
 const a=id?account(id):null, existing=!!a;
 const defaultMode=a?.opening_balance_mode||(existing?'legacy':'statement');
 const optionModes=existing
  ?[['legacy','Conservar configuración anterior (sin fecha)'],['statement','Desde último estado de cuenta'],['current','Desde el saldo actual del banco']]
  :[['statement','Desde último estado de cuenta'],['current','Desde el saldo actual del banco']];
 const latest=a?latestStatement(a.id):null;
 const intro='<div class="wizard-heading"><strong>Asistente para tarjeta de crédito</strong><span id="wizard-label">Paso 1 de 3 · Tarjeta</span></div>'
 +'<p class="tip">No borra movimientos ni mensualidades existentes. El saldo inicial es deuda TOTAL, incluidos saldos MSI anteriores.</p>';
 const p1='<section class="wizard-step" data-wizard-step="0"><h3>1 · Identifica la tarjeta</h3>'
 +field('name','Nombre de tu tarjeta','text',a?.name||'','required maxlength="100"',true)
 +field('bank_name','Banco','text',a?.bank_name||'')
 +field('last4','Últimos cuatro dígitos (opcional)','text',a?.last4||'','maxlength="4" pattern="[0-9]{4}"')
 +field('credit_limit','Límite de crédito','number',a?.credit_limit??'','min="0" step="0.01" required')
 +field('cutoff_day','Día estimado de corte (1–28)','number',a?.cutoff_day??'','min="1" max="28"')
 +field('due_day','Día estimado de pago (1–28)','number',a?.due_day??'','min="1" max="28"')
 +field('cutoff_tolerance_days','Margen de corte (0–3 días)','number',a?.cutoff_tolerance_days??2,'min="0" max="3" required')
 +field('payment_alert_days','Avisar antes del pago (1–7 días)','number',a?.payment_alert_days??2,'min="1" max="7" required')
 +'</section>';
 const p2='<section class="wizard-step hidden" data-wizard-step="1"><h3>2 · Establece el punto de partida</h3>'
 +choose('opening_balance_mode','¿Desde cuándo iniciarás el control?',optionModes,defaultMode,true)
 +field('opening_balance_date','Fecha del saldo inicial (último corte o saldo actual)','date',a?.opening_balance_date||dateToday(),'required',true)
 +field('opening_balance','Deuda TOTAL en esa fecha (incluye MSI anteriores)','number',a?.opening_balance??'','min="0" step="0.01" required',true)
 +'<div class="notice warn full-span">⚠️ Solo registra movimientos POSTERIORES a esta fecha. No vuelvas a cargar compras ya incluidas en la deuda inicial. Los planes MSI históricos se registran solo para controlar sus mensualidades.</div>'
 +(existing?'<p class="tip full-span">Tarjeta ya registrada: los datos y movimientos existentes se conservan. Si cambias la fecha y hay movimientos anteriores, el sistema impedirá guardar para evitar duplicaciones.</p>':'')
 +'</section>';
 const p3='<section class="wizard-step hidden" data-wizard-step="2"><h3>3 · Corte y pagos pendientes</h3>'
 +(latest?'<div class="notice full-span">Esta tarjeta ya tiene un estado de cuenta del '+printDate(latest.close_date)+'. Se conservará sin cambios. Si necesitas corregirlo, usa “Cortes y conciliación”.</div>':'')
 +'<label class="wizard-check full-span"><input type="checkbox" name="include_initial_statement" '+(existing?'':'checked')+'> Registrar también un estado de cuenta (recomendado)</label>'
 +'<fieldset class="wizard-statement full-span"><div class="wizard-statement-grid">'
 +field('stmt_close_date','Fecha de corte bancario','date',existing?'':a?.opening_balance_date||dateToday())
 +field('stmt_due_date','Fecha límite oficial de pago','date','')
 +field('stmt_no_interest_amount','Pago para no generar intereses mostrado por el banco','number','','min="0" step="0.01"')
 +field('stmt_paid_before','Pagos anteriores a la fecha inicial (si el importe bancario era original)','number',0,'min="0" step="0.01"')
 +field('stmt_available','Crédito disponible en la fecha inicial (opcional)','number','','min="0" step="0.01"')
 +'</div><p class="tip">Si el banco ya indica lo que RESTA por pagar, deja los pagos previos en $0. Estos pagos previos NO son movimientos nuevos. El disponible debe corresponder a la fecha inicial indicada en el paso 2.</p></fieldset>'
 +'<p class="tip full-span">Si no tienes tu último corte, desmarca la opción. Luego podrás capturarlo sin inventar montos. Ningún importe de MSI se suma dos veces.</p>'
 +'</section>';
 const controls='<div class="wizard-controls full-span"><button type="button" class="btn outline" data-act="wizard-prev" id="wizard-prev" disabled>← Atrás</button>'
 +'<button type="button" class="btn primary" data-act="wizard-next" id="wizard-next">Siguiente →</button>'
 +'<button type="submit" class="btn primary hidden" id="wizard-save">Guardar tarjeta</button></div>';
 modalOpen(existing?'Configurar tarjeta y saldo inicial':'Nueva tarjeta guiada','credit_wizard',intro+p1+p2+p3+controls,id);
 const form=$('#modal-form');
 form.dataset.step='0';
 form.querySelector('.form-footer').classList.add('hidden');
 wizardUpdate();
}
function wizardUpdate(){
 const form=$('#modal-form');if(form.dataset.table!=='credit_wizard')return;
 const step=Number(form.dataset.step||0);
 form.querySelectorAll('.wizard-step').forEach((el,n)=>el.classList.toggle('hidden',n!==step));
 form.querySelector('#wizard-prev').disabled=step===0;
 form.querySelector('#wizard-next').classList.toggle('hidden',step===2);
 form.querySelector('#wizard-save').classList.toggle('hidden',step!==2);
 const mode=form.elements.opening_balance_mode.value;
 form.elements.opening_balance_date.disabled=mode==='legacy';
 form.elements.opening_balance_date.required=mode!=='legacy';
 form.querySelector('#wizard-label').textContent=['Paso 1 de 3 · Tarjeta','Paso 2 de 3 · Saldo inicial','Paso 3 de 3 · Corte bancario'][step];
 const include=form.elements.include_initial_statement.checked;
 const fieldset=form.querySelector('.wizard-statement');fieldset.disabled=!include;
 fieldset.classList.toggle('hidden',!include);
 for(const key of ['stmt_close_date','stmt_due_date','stmt_no_interest_amount']) form.elements[key].required=include;
}
function wizardGo(delta){
 const f=$('#modal-form');const step=Number(f.dataset.step||0);
 if(delta>0){
  const sec=f.querySelector('[data-wizard-step="'+step+'"]');
  for(const inp of sec.querySelectorAll('input,select')) if(!inp.disabled && !inp.checkValidity()){inp.reportValidity();return;}
  if(step===1){
    const mode=f.elements.opening_balance_mode.value,date=f.elements.opening_balance_date.value;
    if(mode!=='legacy'&&date>dateToday())return toast('No puedes iniciar desde una fecha futura.',true);
    const id=f.dataset.id,a=account(id);
    if(a&&date!==a.opening_balance_date){try{assertBaselineSafe(a,state.movements,mode==='legacy'?null:date)}catch(e){return toast(e.message,true)}}
    if(mode==='statement'&&f.elements.stmt_close_date.value!==date)f.elements.stmt_close_date.value=date;
  }
 }
 f.dataset.step=String(Math.max(0,Math.min(2,step+delta)));wizardUpdate();
}
async function saveCreditWizard(f){
 const fd=new FormData(f),id=f.dataset.id||null;
 const raw=name=>String(fd.get(name)||'').trim();
 const mode=raw('opening_balance_mode'),start=mode==='legacy'?null:raw('opening_balance_date');
 const card={...(id?{id}:{}),name:raw('name'),bank_name:raw('bank_name'),last4:raw('last4'),
  credit_limit:raw('credit_limit'),opening_balance:raw('opening_balance'),opening_balance_date:start,
  opening_balance_mode:mode,cutoff_day:raw('cutoff_day'),due_day:raw('due_day'),
  cutoff_tolerance_days:raw('cutoff_tolerance_days'),payment_alert_days:raw('payment_alert_days')};
 if(!card.name||!Number.isFinite(Number(card.credit_limit))||Number(card.credit_limit)<0||!Number.isFinite(Number(card.opening_balance))||Number(card.opening_balance)<0)
   throw Error('Revisa los datos, el límite y la deuda inicial.');
 if(mode!=='legacy'&&(!start||start>dateToday()))throw Error('Indica una fecha válida para el saldo inicial.');
 if(id&&mode!=='legacy'&&start!==account(id)?.opening_balance_date)assertBaselineSafe(account(id),state.movements,start);
 const include=fd.has('include_initial_statement');
 const stmt=include?{close_date:raw('stmt_close_date'),due_date:raw('stmt_due_date'),
  no_interest_amount:raw('stmt_no_interest_amount'),paid_before_baseline:raw('stmt_paid_before')||'0',
  bank_available:raw('stmt_available'),notes:'Estado inicial registrado en el asistente'}:null;
 if(stmt){
  if(!stmt.close_date||!stmt.due_date||stmt.due_date<stmt.close_date||stmt.close_date>(start||dateToday()))
    throw Error('Revisa las fechas del estado de cuenta.');
  if(stmt.no_interest_amount===''||Number(stmt.no_interest_amount)<0||Number(stmt.paid_before_baseline)>Number(stmt.no_interest_amount))
    throw Error('Indica el pago bancario y revisa los pagos previos.');
  if(mode==='statement'&&stmt.close_date!==start)throw Error('En modo último corte, el corte y saldo inicial deben tener la misma fecha.');
 }
 if(mode==='legacy'&&stmt)throw Error('Primero configura una fecha de saldo inicial para registrar el corte inicial.');
 if(mode==='legacy'&&!id)throw Error('Las tarjetas nuevas necesitan una fecha de inicio.');
 if(mode==='demo'){
  let target=id?state.accounts.find(x=>x.id===id):null;
  if(target)Object.assign(target,card);else{
   card.id=uid();card.kind='credit';state.accounts.push({...card});
  }
  if(stmt)state.statements.push({id:uid(),account_id:card.id,...stmt,available_at:start,paid_before_baseline:Number(stmt.paid_before_baseline),no_interest_amount:Number(stmt.no_interest_amount)});
 }else{
  const {error}=await sb.rpc('save_credit_start',{p_card:card,p_initial_statement:stmt});
  if(error)throw error;await loadData();
 }
}

function updateMovementForm(){
 const form=$('#modal-form');if(form.dataset.table!=='movements')return;
 const type=form.elements.kind.value,payment=type==='payment',accSelect=form.elements.account_id;
 for(const o of accSelect.options){const a=account(o.value);o.disabled=payment&&a?.kind!=='credit';o.hidden=o.disabled;}
 if(payment && accSelect.options[accSelect.selectedIndex]?.disabled){const first=[...accSelect.options].find(o=>!o.disabled);if(first)accSelect.value=first.value;}
 for(const name of ['category','merchant'])form.elements[name]?.closest('label')?.classList.toggle('hidden',payment);
 const st=form.elements.statement_id,accountId=accSelect.value;
 for(const o of st.options){const related=state.statements.find(x=>x.id===o.value);o.disabled=!!related&&(related.account_id!==accountId||!payment);o.hidden=o.disabled;}
 if(st.options[st.selectedIndex]?.disabled)st.value='';
 st.closest('label')?.classList.toggle('hidden',!payment);
 const description=form.elements.description,descWrapper=description?.closest('label');
 if(descWrapper?.firstChild)descWrapper.firstChild.textContent=payment?'Referencia / nota (opcional)':'Concepto';
 form.querySelector('#payment-hint')?.classList.toggle('hidden',!payment);
 const submit=form.querySelector('[type=submit]');if(submit)submit.textContent=payment?'Guardar pago':'Guardar registro';
 $('#modal-title').textContent=form.dataset.id?'Editar movimiento':payment?'Registrar pago a tarjeta':'Registrar movimiento';
}

