const FIELDS={accounts:['name','kind','bank_name','last4','credit_limit','opening_balance','cutoff_day','due_day','cutoff_tolerance_days','payment_alert_days'],movements:['account_id','kind','transaction_date','amount','description','category','merchant','statement_id'],installments:['account_id','description','original_amount','months','first_charge_month','installments_paid','monthly_amount','status','entry_type','movement_id'],statements:['account_id','period_start','close_date','due_date','no_interest_amount','paid_before_baseline','bank_available','available_at','notes'],loans:['name','lender','asset_value','down_payment','financed_amount','monthly_payment','term_months','annual_rate','start_date','next_due_date','status','payroll_deduction','notes'],loan_payments:['loan_id','payment_date','amount','principal_part','interest_part','note'],recurring_bills:['name','amount','frequency','next_date','due_day','direction','category','account_id','active','notes'],recurring_checks:['bill_id','occurrence_date','note'],budgets:['category','month','amount']};
const numericFields=new Set(['paid_before_baseline','credit_limit','opening_balance','cutoff_day','due_day','cutoff_tolerance_days','payment_alert_days','amount','original_amount','months','installments_paid','monthly_amount','no_interest_amount','bank_available','asset_value','down_payment','financed_amount','monthly_payment','term_months','annual_rate','principal_part','interest_part']);
const optionalNull=new Set(['next_date','account_id','available_at','movement_id','last4','cutoff_day','due_day','statement_id','period_start','bank_available','monthly_amount','asset_value','monthly_payment','term_months','annual_rate','start_date','next_due_date','principal_part','interest_part']);
function collect(f,table){const fd=new FormData(f),o={};for(const key of FIELDS[table]){if(key==='payroll_deduction'){o[key]=fd.has(key);continue}let v=fd.get(key);if((key==='first_charge_month'||key==='month')&&v&&v.length===7)v+='-01';if(key==='active')v=v==='true';if(v===''&&optionalNull.has(key)){o[key]=null;continue}o[key]=numericFields.has(key)?Number(v):v}return o}
function validate(table,o,id){if(table==='movements'){let a=account(o.account_id);if(!a)throw Error('Selecciona una cuenta.');assertMovementAfterBaseline(a,o);if(o.statement_id){let st=state.statements.find(s=>s.id===o.statement_id);if(o.kind!=='payment'||st?.account_id!==o.account_id)throw Error('Vincula estados de cuenta solo a pagos de esa misma tarjeta.');}if(o.kind==='payment'&&a.kind!=='credit')throw Error('“Pago a tarjeta” se registra en la tarjeta de crédito. Para salida de débito usa “Salida por transferencia”.');if(['purchase','fee','interest'].includes(o.kind)&&a.kind!=='credit')throw Error('Usa “Gasto” para débito o efectivo, y “Compra” para tarjeta de crédito.');if(o.kind==='expense'&&a.kind==='credit')throw Error('En tarjeta de crédito, los gastos se registran como “Compra”.');}
 if(table==='installments'){if(o.installments_paid>o.months)throw Error('No puedes haber pagado más mensualidades que las contratadas.');if(o.entry_type==='new_purchase'){const m=state.movements.find(m=>m.id===o.movement_id);if(!m||m.account_id!==o.account_id||m.kind!=='purchase')throw Error('El MSI nuevo requiere vincular la compra de esa tarjeta registrada en Movimientos.');assertMovementAfterBaseline(account(o.account_id),m)}else if(o.movement_id)throw Error('Si el plan MSI ya estaba en el saldo inicial no vincules otra compra.');}if(table==='installments'&&o.monthly_amount!==null&&Math.round(o.monthly_amount*100)*(o.months-1)>=Math.round(o.original_amount*100))throw Error('La mensualidad indicada no puede superar el total financiado.');
 if(table==='accounts'&&(o.cutoff_tolerance_days<0||o.cutoff_tolerance_days>3||o.payment_alert_days<1||o.payment_alert_days>7))throw Error('Revisa el margen de corte y los días de aviso.');
 if(table==='statements'&&(o.due_date<o.close_date||o.paid_before_baseline<0||o.paid_before_baseline>o.no_interest_amount))throw Error('Revisa las fechas y pagos anteriores del corte; no pueden superar el pago oficial.');
 if(table==='loan_payments'&&o.principal_part!==null&&o.interest_part!==null&&o.principal_part+o.interest_part>o.amount+0.001)throw Error('Capital más intereses no puede superar el pago total.');if(table==='recurring_bills'&&(o.amount<=0||o.due_day<1||o.due_day>31))throw Error('Revisa monto y fecha del cargo fijo.');if(table==='budgets'&&(o.amount<=0||!o.month||o.month.slice(-2)!=='01'))throw Error('Revisa el monto y el mes del presupuesto.');}
async function persist(table,row,id){if(mode==='demo'){if(id){let i=state[table].findIndex(x=>x.id===id);if(i<0)throw Error('Registro no encontrado');state[table][i]={...state[table][i],...row}}else state[table].push({...row,id:uid()});return}
let query=id?sb.from(table).update(row).eq('id',id).select():sb.from(table).insert(row).select();const {error}=await query;if(error)throw error;await loadData()}
async function remove(table,id){if(mode==='demo'){state[table]=state[table].filter(x=>x.id!==id);return}const {error}=await sb.from(table).delete().eq('id',id);if(error)throw error;await loadData()}
async function loadData(){const newS=fresh();for(const t of DB_TABLES){const {data,error}=await sb.from(t).select('*');if(error)throw Error(`No se pudo leer ${t}: ${error.message}`);newS[t]=data||[]}state=newS}
async function onSubmit(e){e.preventDefault();const f=e.target,table=f.dataset.table,id=f.dataset.id||null;const btn=f.querySelector('[type=submit]:not(.hidden)');if(btn?.disabled)return;try{if(btn)btn.disabled=true;if(table==='credit_wizard')await saveCreditWizard(f);else if(table==='recurring_review')await saveRecurringReview(featureHost(),f);else if(table==='msi_link')await saveMsiLink(featureHost(),f);else if(table==='card_cycle')await saveCycleSettings(featureHost(),f);else{const row=collect(f,table);if(table==='movements'&&row.kind==='payment'&&!row.description?.trim())row.description='Pago a tarjeta';validate(table,row,id);await persist(table,row,id)}modalClose();toast(table==='recurring_review'?'Recurrente confirmado y registrado una sola vez ✓':table==='msi_link'?'Mensualidad vinculada a un pago sin duplicar el saldo ✓':table==='card_cycle'?'Ciclo bancario configurado; pagos previstos actualizados ✓':'Registro guardado correctamente ✓');render()}catch(err){toast(err.message||'Error al guardar',true)}finally{if(btn)btn.disabled=false}}
async function deleteItem(table,id){const depends={accounts:[...state.movements,...state.statements,...state.installments].some(x=>x.account_id===id),loans:state.loan_payments.some(x=>x.loan_id===id),movements:state.installments.some(x=>x.movement_id===id),statements:state.movements.some(x=>x.statement_id===id)};if(depends[table])return toast('No se puede borrar: hay registros relacionados. Primero corrígelos o desvincúlalos.',true);if(!confirm('¿Eliminar este registro? Esta acción no se puede deshacer.'))return;try{await remove(table,id);render();toast('Registro eliminado.')}catch(e){toast(e.message,true)}}
function exportCSV(){const cols=['transaction_date','account','kind','amount','category','description','merchant'];const rows=[cols,...state.movements.map(m=>[m.transaction_date,account(m.account_id)?.name||'',m.kind,num(m.amount).toFixed(2),m.category,m.description,m.merchant])];const escapeCSV=v=>'"'+String(v??'').replaceAll('"','""')+'"';let blob=new Blob(['\ufeff'+rows.map(r=>r.map(escapeCSV).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`brujula-movimientos-${dateToday()}.csv`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('CSV descargado: guárdalo de forma segura.')} 
async function handleAction(b){if(paydayAction(b,render))return;if(accountDetailAction(b,featureHost()))return;if(await extraAction(b,featureHost()))return;if(await importClick(b,featureHost()))return;const act=b.dataset.act,id=b.dataset.id;if(act==='card-cycle')return openCycleSettings(featureHost(),id);if(act==='cycle-statement')return openForm('statements',null,id);if(act==='msi-link'||act==='advance-installment')return openMsiLink(featureHost(),id);if(act==='wizard-next')return wizardGo(1);if(act==='wizard-prev')return wizardGo(-1);if(act==='close')return modalClose();if(act==='new-account')return openCreditWizard();if(act==='new-cash-account')return openForm('accounts');if(act==='new-movement')return openForm('movements');if(act==='new-installment')return openForm('installments');if(act==='new-statement')return openForm('statements');if(act==='card-statement')return openForm('statements',null,id);if(act==='new-loan')return openForm('loans');if(act==='new-loan-payment')return openForm('loan_payments',null,id);if(act==='edit-account'){const a=account(id);return a?.kind==='credit'?openCreditWizard(id):openForm('accounts',id)}if(act==='edit-movement')return openForm('movements',id);if(act==='edit-installment')return openForm('installments',id);if(act==='edit-statement')return openForm('statements',id);if(act==='edit-loan')return openForm('loans',id);if(act==='edit-loan-payment')return openForm('loan_payments',id);if(act==='delete')return deleteItem(b.dataset.table,id);if(act==='export')return exportCSV();}
async function refreshFromCloud(manual=false){if(mode!=='live'||!sb)return;if(!navigator.onLine){if(manual)toast('Sin internet: los registros en la nube no están disponibles.',true);return}if(!$('#modal').classList.contains('hidden')){if(manual)toast('Cierra primero el formulario sin guardar para actualizar.',true);return}try{await loadData();render();if(manual)toast('Datos actualizados desde Supabase ✓')}catch(e){toast('No se pudo sincronizar: '+e.message,true)}}
async function logout(){if(mode==='live'&&sb){await sb.auth.signOut()}mode='demo';state=fresh();$('#shell').classList.add('hidden');$('#gate').classList.remove('hidden')}
const passwordRecovery=createPasswordRecovery({getClient:()=>sb,toast});
async function authConnect(){let cfg=window.FINANZAS_CONFIG||{};if(!cfg.supabaseUrl||!cfg.supabasePublishableKey){$('#auth-notice').textContent='No se pudo habilitar el acceso a Supabase. Intenta actualizar Brújula.';return}try{const pkg=await import('https://esm.sh/@supabase/supabase-js@2.49.10');sb=pkg.createClient(cfg.supabaseUrl,cfg.supabasePublishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});passwordRecovery.bindClient(sb);const {data:{session},error}=await sb.auth.getSession();if(error)throw error;if(passwordRecovery.handleInitialSession(session))return;if(session){mode='live';await loadData();showShell()}}catch(e){$('#auth-notice').textContent='No fue posible conectar con la base de datos: '+e.message;toast('Error de conexión a Supabase.',true)}}
function bind(){document.addEventListener('click',async e=>{const nav=e.target.closest('[data-page]');if(nav){page=nav.dataset.page;render();if(page==='movements')updateMovementTable();window.scrollTo({top:0,behavior:'smooth'});return}let b=e.target.closest('[data-act]');if(b)await handleAction(b)});$('#quick-add').addEventListener('click',()=>openForm('movements'));$('#sync-now').addEventListener('click',()=>refreshFromCloud(true));window.addEventListener('focus',()=>refreshFromCloud(false));document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshFromCloud(false)});$('#close-modal').addEventListener('click',modalClose);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))modalClose()});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').classList.contains('hidden'))modalClose()});$('#modal-form').addEventListener('submit',onSubmit);$('#modal-form').addEventListener('change',e=>{if(['opening_balance_mode','include_initial_statement'].includes(e.target.name))wizardUpdate();if(['kind','account_id'].includes(e.target.name))updateMovementForm();if(e.target.name==='payment_mode')updateMsiMode()});document.addEventListener('change',e=>{importChange(e,featureHost());extraChange(e,featureHost());accountDetailChange(e,featureHost())});$('#content').addEventListener('input',e=>{if(['mov-search','mov-account','mov-kind'].includes(e.target.id))updateMovementTable()});$('#content').addEventListener('change',e=>{if(['mov-search','mov-account','mov-kind'].includes(e.target.id))updateMovementTable()});$('#logout').addEventListener('click',logout);$('#demo').addEventListener('click',()=>{mode='demo';state=sample();page='dashboard';showShell()});$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();if(!sb)return;try{const email=$('#auth-email').value,password=$('#auth-pass').value;const {error}=await sb.auth.signInWithPassword({email,password});if(error)throw error;mode='live';await loadData();page='dashboard';showShell()}catch(e){$('#auth-notice').textContent=e.message;toast('No fue posible entrar.',true)}});$('#signup').addEventListener('click',async()=>{if(!sb)return;let email=$('#auth-email').value,password=$('#auth-pass').value;if(!email||password.length<6)return toast('Ingresa correo y contraseña de 6 caracteres mínimo.',true);try{let {error}=await sb.auth.signUp({email,password,options:{emailRedirectTo:'https://javi-jim2026.github.io/brujula-finanzas/'}});if(error)throw error;$('#auth-notice').textContent='Registro solicitado. Revisa tu correo si está activada la confirmación de email.';toast('Verifica tu correo para continuar.')}catch(e){toast(e.message,true)}})}
passwordRecovery.setup();setupInstallSupport();bind();authConnect();

// Instalación opcional como aplicación web. Solo se almacena el cascarón, nunca registros financieros en caché.
if ('serviceWorker' in navigator && (location.protocol === 'https:' || location.hostname === 'localhost')) { window.addEventListener('load', () => navigator.serviceWorker.register('./sw.js').catch(() => {})); }
